import 'package:flutter/material.dart';
import 'home_screen.dart';import 'mask_screen.dart';import 'send_screen.dart';import 'vault_screen.dart';import 'history_screen.dart';import 'settings_screen.dart';
class AppShell extends StatefulWidget{const AppShell({super.key});@override State<AppShell> createState()=>_AppShellState();}
class _AppShellState extends State<AppShell>{int i=0;late final pages=[HomeScreen(onNavigate:(n)=>setState(()=>i=n)),const MaskScreen(),const SendScreen(),const VaultScreen(),const HistoryScreen(),const SettingsScreen()];final labels=['Home','Mask','Send','Vault','History','Settings'];final icons=[Icons.home_rounded,Icons.image_search_rounded,Icons.send_rounded,Icons.folder_rounded,Icons.history_rounded,Icons.settings_rounded];@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:pages[i]),bottomNavigationBar:NavigationBar(height:70,selectedIndex:i,onDestinationSelected:(n)=>setState(()=>i=n),indicatorColor:const Color(0xFFFFC900),destinations:[for(int n=0;n<6;n++)NavigationDestination(icon:Icon(icons[n]),label:labels[n]) ]));}
